import os

d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}

import re
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Keys:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: {len(v)}x{len(v[0]) if v else 0}")

import numpy as np

in_input = G['Demo pair 1 input']
in_output = G['Demo pair 1 output']

Iinput = np.array(in_input)
Ioutput = np.array(in_output)

# Let me check each input row and see where its values appear in output
# Maybe in cols 14-27 instead?
print("Checking if input rows appear in output right half:")
for k in range(14):
    right = Ioutput[k, 14:28]
    match = np.array_equal(Iinput[k, :], right)
    if match:
        print(f"  Input row {k} matches output row {k}, cols 14-27")
    else:
        # Check if it appears anywhere
        found = False
        for rk in range(28):
            for ck in range(14):
                if np.array_equal(Ioutput[rk, ck:ck+14], Iinput[k, :]):
                    print(f"  Input row {k} found at output[{rk}, :{ck+14}]")
                    found = True
                    break
            if found:
                break
        if not found:
            print(f"  Input row {k}: NOT FOUND as row")

print("\n--- First 14 rows of output (with indices) ---")
for r in range(14):
    print(f"Row {r}: {Ioutput[r]}")

